  "devEnv.warningBodySrt": "AI はどのチャットでも、チームサーバーで任意のプログラムを実行できます。コマンドは、チャットした人が読めるすべてのチームフォルダーを読めます。書き込めるのは、そのチャットのプロジェクトフォルダーとその人の個人フォルダーだけです。サンドボックスは、サーバーのデータ、秘密の値、他の人の個人フォルダー、その人が開けないフォルダーを隠します。\n- コマンドは、許可されたサイトを通じてデータを外部に送れます。GitHub、npm、PyPI はアップロードを受け付けるため、コマンドはその人が読めるすべてのファイルを送れます。\n- 各自は、チャットで確認されたときに自分のコマンド用のサイトを追加で許可したり、自分だけフルインターネットをオンにしたりできます。その人のコマンドは、そのサイトにもデータを送れます。管理者の操作は不要です。\n- コマンドは、その人が読めるファイルを、より多くの人が見るプロジェクトフォルダーにコピーできます。\n- その人の個人フォルダーでコマンドが変更したファイルには、変更記録と以前のバージョンがありません。\n- プロジェクトフォルダーに書き込める人は全員同じフォルダーを使います。ある人の変更は、別の人の次のコマンドに影響します。\n- ログインはありません。git push などのコマンドは自分のコンピューターで実行してください。\n- メモリを使いすぎた実行は停止します。チームの重いジョブはキューで待ちます。\n- コマンドはアクティビティ記録に残ります。\nこの機能は実験的なもので、いつでもオフにできます。",
